// How long the LED stays on (and off), in milliseconds.
const unsigned long BLINK_TIME = 1000;

void setup() {
  // Tell the board this pin is an output (it sends power out).
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);  // LED on
  delay(BLINK_TIME);                // wait 1 second
  digitalWrite(LED_BUILTIN, LOW);   // LED off
  delay(BLINK_TIME);                // wait 1 second
}

const int BUTTON_PIN = 2;
const int LED_PIN = LED_BUILTIN;
const unsigned long DEBOUNCE_MS = 50;  // ignore wobbles shorter than this

bool ledOn = false;
int lastReading = HIGH;          // what the pin said last time
int stableState = HIGH;          // the "real" button state after debounce
unsigned long lastChangeTime = 0;

void setup() {
  // INPUT_PULLUP keeps the pin HIGH until the button connects it to GND.
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int reading = digitalRead(BUTTON_PIN);

  // The reading changed, so restart the debounce timer.
  if (reading != lastReading) {
    lastChangeTime = millis();
  }

  // It stayed the same long enough, so trust it.
  if (millis() - lastChangeTime > DEBOUNCE_MS && reading != stableState) {
    stableState = reading;

    // LOW means pressed (the pin is pulled to GND).
    if (stableState == LOW) {
      ledOn = !ledOn;
      digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
      Serial.println(ledOn ? "LED ON" : "LED OFF");
    }
  }

  lastReading = reading;
}

const int BUZZER_PIN = 8;

// Note pitches in Hz (0 means a rest).
const int NOTE_C = 262, NOTE_D = 294, NOTE_E = 330, NOTE_F = 349, NOTE_G = 392, NOTE_A = 440;

const int melody[] = {
  NOTE_C, NOTE_C, NOTE_G, NOTE_G, NOTE_A, NOTE_A, NOTE_G, 0,
  NOTE_F, NOTE_F, NOTE_E, NOTE_E, NOTE_D, NOTE_D, NOTE_C, 0
};

// How long each note lasts: 4 = quarter note, 2 = half note.
const int beats[] = {
  4, 4, 4, 4, 4, 4, 2, 4,
  4, 4, 4, 4, 4, 4, 2, 4
};

const int NOTE_COUNT = sizeof(melody) / sizeof(melody[0]);
const int WHOLE_NOTE_MS = 1600;  // smaller = faster song

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
}

void loop() {
  for (int i = 0; i < NOTE_COUNT; i++) {
    int noteLength = WHOLE_NOTE_MS / beats[i];

    if (melody[i] > 0) {
      tone(BUZZER_PIN, melody[i], noteLength);
    }

    // Wait a little longer than the note so notes don't blur together.
    delay(noteLength * 13 / 10);
    noTone(BUZZER_PIN);
  }

  delay(2000);  // pause before playing again
}

// Tip: pull the little jumper off the L298N's ENA pins so the Arduino can set the speed.
const int ENA_PIN = 9;  // speed pin (must be a ~PWM pin)
const int IN1_PIN = 8;  // direction pin 1
const int IN2_PIN = 7;  // direction pin 2

void setup() {
  pinMode(ENA_PIN, OUTPUT);
  pinMode(IN1_PIN, OUTPUT);
  pinMode(IN2_PIN, OUTPUT);
  Serial.begin(9600);
}

// Set the direction: true = forward, false = backward.
void setDirection(bool forward) {
  digitalWrite(IN1_PIN, forward ? HIGH : LOW);
  digitalWrite(IN2_PIN, forward ? LOW : HIGH);
}

// Stop the motor.
void stopMotor() {
  digitalWrite(IN1_PIN, LOW);
  digitalWrite(IN2_PIN, LOW);
  analogWrite(ENA_PIN, 0);
}

// Speed up from slow to full, then slow back down.
void rampSpeed() {
  for (int speed = 80; speed <= 255; speed += 5) {
    analogWrite(ENA_PIN, speed);
    delay(30);
  }
  for (int speed = 255; speed >= 80; speed -= 5) {
    analogWrite(ENA_PIN, speed);
    delay(30);
  }
}

void loop() {
  Serial.println("Forward");
  setDirection(true);
  rampSpeed();

  stopMotor();
  delay(1000);

  Serial.println("Backward");
  setDirection(false);
  rampSpeed();

  stopMotor();
  delay(1000);
}

#include <Adafruit_NeoPixel.h>

const int LED_PIN = 6;
const int LED_COUNT = 30;   // change to how many LEDs your strip has
const int BRIGHTNESS = 50;  // 0 to 255 (keep it low so USB power is enough)

Adafruit_NeoPixel strip(LED_COUNT, LED_PIN, NEO_GRB + NEO_KHZ800);

// Where the rainbow starts. It moves a bit each frame.
uint16_t firstHue = 0;

void setup() {
  strip.begin();
  strip.setBrightness(BRIGHTNESS);
  strip.show();  // start with all LEDs off
}

void loop() {
  for (uint16_t i = 0; i < strip.numPixels(); i++) {
    // Spread one full rainbow (65536 hues) across the strip.
    uint16_t hue = firstHue + (uint32_t)i * 65536UL / strip.numPixels();
    uint32_t color = strip.gamma32(strip.ColorHSV(hue));
    strip.setPixelColor(i, color);
  }
  strip.show();

  firstHue += 256;  // slide the rainbow along
  delay(20);
}

const int SENSOR_PIN = A0;
const int LED_PIN = 9;  // a ~PWM pin so we can dim it

// Change these after watching the Serial Monitor in your room.
const int DARK_READING = 200;    // reading when it's dark
const int BRIGHT_READING = 800;  // reading when it's bright

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int light = analogRead(SENSOR_PIN);  // 0 (dark) to 1023 (bright)

  // Dark room -> bright LED. Bright room -> LED off.
  int brightness = map(light, DARK_READING, BRIGHT_READING, 255, 0);
  brightness = constrain(brightness, 0, 255);
  analogWrite(LED_PIN, brightness);

  Serial.print("Light: ");
  Serial.print(light);
  Serial.print("  LED: ");
  Serial.println(brightness);

  delay(100);
}

const int X_PIN = A0;
const int Y_PIN = A1;
const int BUTTON_PIN = 2;
const int DEAD_ZONE = 150;  // how far from the middle before it counts

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);  // pressed = LOW
  Serial.begin(9600);
}

void loop() {
  int x = analogRead(X_PIN);  // 0 to 1023, about 512 in the middle
  int y = analogRead(Y_PIN);
  bool pressed = digitalRead(BUTTON_PIN) == LOW;

  // Work out the direction.
  const char *direction = "center";
  if (x < 512 - DEAD_ZONE) direction = "left";
  else if (x > 512 + DEAD_ZONE) direction = "right";
  else if (y < 512 - DEAD_ZONE) direction = "up";
  else if (y > 512 + DEAD_ZONE) direction = "down";

  Serial.print("X: ");
  Serial.print(x);
  Serial.print("  Y: ");
  Serial.print(y);
  Serial.print("  Button: ");
  Serial.print(pressed ? "PRESSED" : "-");
  Serial.print("  Direction: ");
  Serial.println(direction);

  delay(100);
}

#include <Servo.h>

const int SERVO_PIN = 9;
const int STEP_DELAY = 15;  // smaller = faster sweep

Servo myServo;

void setup() {
  myServo.attach(SERVO_PIN);
}

void loop() {
  // Go from 0 up to 180 degrees.
  for (int angle = 0; angle <= 180; angle++) {
    myServo.write(angle);
    delay(STEP_DELAY);
  }
  // Come back down from 180 to 0.
  for (int angle = 180; angle >= 0; angle--) {
    myServo.write(angle);
    delay(STEP_DELAY);
  }
}

