// A class is a blueprint. Each Pet we make from it is an "object".
class Pet {
public:
  // The constructor runs when a new Pet is made.
  Pet(const std::string &name, const std::string &species)
      : name_(name), species_(species) {}

  void feed() {
    hunger_ = clamp(hunger_ - 30);
    std::cout << name_ << " munches some food. Yum!\n";
  }

  void play() {
    happiness_ = clamp(happiness_ + 20);
    hunger_ = clamp(hunger_ + 10);  // playing makes you hungry
    std::cout << name_ << " plays fetch!\n";
  }

  void showStatus() const {
    std::cout << name_ << " the " << species_ << " - hunger: " << hunger_
              << "/100, happiness: " << happiness_ << "/100";
    if (hunger_ > 70) std::cout << " (very hungry!)";
    std::cout << "\n";
  }

  const std::string &getName() const { return name_; }

private:
  // Private data: only the Pet's own functions can change it.
  std::string name_;
  std::string species_;
  int hunger_ = 50;
  int happiness_ = 50;

  // Keep a value between 0 and 100.
  static int clamp(int value) {
    if (value < 0) return 0;
    if (value > 100) return 100;
    return value;
  }
};

int main() {
  // Two different objects made from the same class.
  Pet dog("Biscuit", "dog");
  Pet cat("Pixel", "cat");

  dog.showStatus();
  cat.showStatus();
  std::cout << "\n";

  dog.play();
  dog.play();
  cat.feed();
  std::cout << "\n";

  dog.showStatus();
  cat.showStatus();

  std::cout << "\nRemember to feed " << dog.getName() << " soon!\n";
  return 0;
}

#include <chrono>
#include <iostream>
#include <sstream>
#include <string>
#include <thread>

int main() {
  int seconds = 0;
  std::string line;

  // Keep asking until we get a number from 1 to 3600.
  while (true) {
    std::cout << "Count down from how many seconds? (1-3600): ";
    if (!std::getline(std::cin, line)) return 0;  // input closed
    std::istringstream in(line);
    char extra;
    if (in >> seconds && !(in >> extra) && seconds >= 1 && seconds <= 3600) break;
    std::cout << "Please type a whole number from 1 to 3600.\n";
  }

  // Remember when we started.
  auto start = std::chrono::steady_clock::now();

  for (int left = seconds; left > 0; left--) {
    int minutes = left / 60;
    int secs = left % 60;
    // \r jumps back to the start of the line so the number updates in place.
    std::cout << "\r" << minutes << ":" << (secs < 10 ? "0" : "") << secs << "   " << std::flush;
    std::this_thread::sleep_for(std::chrono::seconds(1));
  }

  auto end = std::chrono::steady_clock::now();
  auto tookMs = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

  std::cout << "\r0:00   \nTime's up! Beep beep beep!\n";
  std::cout << "That really took " << tookMs / 1000.0 << " seconds.\n";
  return 0;
}

