const std::string FILE_NAME = "notes.txt";

int main() {
  // Ask for a note.
  std::cout << "Type a note to save: ";
  std::string note;
  if (!std::getline(std::cin, note) || note.empty()) {
    std::cout << "No note typed, nothing saved.\n";
  } else {
    // std::ios::app means "add to the end" instead of wiping the file.
    std::ofstream out(FILE_NAME, std::ios::app);
    if (!out) {
      std::cout << "Couldn't open " << FILE_NAME << " for writing.\n";
      return 1;
    }
    out << note << "\n";
    std::cout << "Saved!\n";
  }  // the file closes by itself here

  // Read the file back, one line at a time.
  std::ifstream in(FILE_NAME);
  if (!in) {
    std::cout << "There's no " << FILE_NAME << " yet.\n";
    return 0;
  }

  std::cout << "\n--- Everything in " << FILE_NAME << " ---\n";
  std::string line;
  int lineNumber = 1;
  while (std::getline(in, line)) {
    std::cout << lineNumber << ": " << line << "\n";
    lineNumber++;
  }
  std::cout << "--- Total notes: " << (lineNumber - 1) << " ---\n";
  return 0;
}

#include <cmath>
#include <iostream>
#include <sstream>
#include <string>

int main() {
  std::cout << "Calculator! Type things like 7 + 5 or 9 / 2. Use + - * / % ^\n"
            << "Type q to quit.\n";

  std::string line;
  while (true) {
    std::cout << "\n> ";
    if (!std::getline(std::cin, line)) break;  // input closed
    if (line == "q" || line == "quit") break;

    // Split the line into: number, operator, number.
    std::istringstream in(line);
    double a = 0, b = 0;
    char op = 0, extra = 0;
    if (!(in >> a >> op >> b) || (in >> extra)) {
      std::cout << "I didn't get that. Try: 3 + 4\n";
      continue;
    }

    double answer = 0;
    bool ok = true;
    switch (op) {
      case '+': answer = a + b; break;
      case '-': answer = a - b; break;
      case '*': case 'x': answer = a * b; break;
      case '/':
        if (b == 0) { std::cout << "You can't divide by zero!\n"; ok = false; }
        else answer = a / b;
        break;
      case '%':
        if (b == 0) { std::cout << "You can't divide by zero!\n"; ok = false; }
        else answer = std::fmod(a, b);
        break;
      case '^': answer = std::pow(a, b); break;
      default:
        std::cout << "I don't know the '" << op << "' sign. Use + - * / % ^\n";
        ok = false;
    }

    if (ok) std::cout << "= " << answer << "\n";
  }

  std::cout << "Bye!\n";
  return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

// Print every item in a vector of strings.
void printAll(const std::vector<std::string> &items) {
  std::cout << "[";
  for (std::size_t i = 0; i < items.size(); i++) {
    std::cout << items[i];
    if (i + 1 < items.size()) std::cout << ", ";
  }
  std::cout << "]  (size " << items.size() << ")\n";
}

int main() {
  // A vector is a list that can grow and shrink.
  std::vector<std::string> inventory = {"sword", "shield"};
  printAll(inventory);

  // Add to the end.
  inventory.push_back("potion");
  inventory.push_back("map");
  std::cout << "After adding: ";
  printAll(inventory);

  // Read and change an item by its position (starts at 0!).
  std::cout << "First item: " << inventory[0] << "\n";
  inventory[1] = "golden shield";
  std::cout << "After upgrade: ";
  printAll(inventory);

  // Find an item.
  auto spot = std::find(inventory.begin(), inventory.end(), "potion");
  if (spot != inventory.end()) {
    std::cout << "Found potion at position " << (spot - inventory.begin()) << "\n";
    inventory.erase(spot);  // use it up
  }
  std::cout << "After using potion: ";
  printAll(inventory);

  // Remove the last item.
  inventory.pop_back();
  std::cout << "After dropping last item: ";
  printAll(inventory);

  // A vector of numbers, plus a "for each" loop to add them up.
  std::vector<int> scores = {40, 75, 90, 15};
  int total = 0;
  for (int score : scores) total += score;
  std::cout << "Total score: " << total << "\n";

  // Sort the numbers from small to big.
  std::sort(scores.begin(), scores.end());
  std::cout << "Sorted scores:";
  for (int score : scores) std::cout << " " << score;
  std::cout << "\n";

  // Empty it out.
  inventory.clear();
  std::cout << "Inventory empty? " << (inventory.empty() ? "yes" : "no") << "\n";
  return 0;
}

#include <cctype>
#include <iostream>
#include <random>
#include <string>
#include <vector>

int main() {
  const std::vector<std::string> words = {"robot", "planet", "castle", "dragon",
                                          "rocket", "pizza", "jungle", "laptop"};

  std::random_device seed;
  std::mt19937 rng(seed());
  std::uniform_int_distribution<std::size_t> pick(0, words.size() - 1);

  const std::string secret = words[pick(rng)];
  std::string shown(secret.size(), '_');  // what the player sees, like "_ _ _"
  std::string guessed;                     // letters tried so far
  int lives = 6;

  std::cout << "Hangman! Guess the word one letter at a time.\n";

  while (lives > 0 && shown != secret) {
    std::cout << "\nWord: ";
    for (char c : shown) std::cout << c << ' ';
    std::cout << "\nLives: " << lives << "   Tried: " << guessed << "\nLetter: ";

    std::string line;
    if (!std::getline(std::cin, line)) return 0;  // input closed

    // Only accept exactly one letter.
    if (line.size() != 1 || !std::isalpha(static_cast<unsigned char>(line[0]))) {
      std::cout << "Please type one letter.\n";
      continue;
    }
    char letter = static_cast<char>(std::tolower(static_cast<unsigned char>(line[0])));

    if (guessed.find(letter) != std::string::npos) {
      std::cout << "You already tried '" << letter << "'.\n";
      continue;
    }
    guessed += letter;

    // Reveal every spot where the letter appears.
    bool found = false;
    for (std::size_t i = 0; i < secret.size(); i++) {
      if (secret[i] == letter) {
        shown[i] = letter;
        found = true;
      }
    }

    if (found) {
      std::cout << "Nice! '" << letter << "' is in the word.\n";
    } else {
      lives--;
      std::cout << "Nope, no '" << letter << "'.\n";
    }
  }

  if (shown == secret) {
    std::cout << "\nYou won! The word was " << secret << ".\n";
  } else {
    std::cout << "\nOut of lives! The word was " << secret << ".\n";
  }
  return 0;
}

#include <iostream>
